// src/react/vector.ts
var DEFAULT_PALETTE = {
  background: "#e8e8e6",
  water: "#c7d2d8",
  waterway: "#b9c6cd",
  green: "#dfe3da",
  roadCasing: "#d0d0cd",
  roadMajor: "#ffffff",
  roadSecondary: "#fafafa",
  roadMinor: "#f2f2f0",
  rail: "#c4c4c1",
  placeText: "#3d4043",
  roadText: "#7c7f83",
  textHalo: "#ffffff"
};
var OSM_ATTR = '&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank">OpenStreetMap</a> contributors';
var VARDHAN_TILES_ORIGIN = "https://maps.vardhansystems.in";
var DEFAULT_PMTILES = `${VARDHAN_TILES_ORIGIN}/beyond-tgap.pmtiles`;
var DEFAULT_GLYPHS = `${VARDHAN_TILES_ORIGIN}/fonts/{fontstack}/{range}.pbf`;
var DEFAULT_FONT_STACK = "Noto Sans Regular";
var SRC = "osm";
function labelField(lang) {
  if (lang === "local") return ["coalesce", ["get", "name"], ""];
  const first = lang === "en" ? "name:en" : "name:latin";
  return ["coalesce", ["get", first], ["get", "name:en"], ["get", "name"], ""];
}
function vectorBasemapStyle(options = {}) {
  const {
    pmtilesUrl = DEFAULT_PMTILES,
    glyphsUrl = DEFAULT_GLYPHS,
    attribution = OSM_ATTR,
    colors,
    lang = "latin",
    fontStack = DEFAULT_FONT_STACK
  } = options;
  const c = { ...DEFAULT_PALETTE, ...colors ?? {} };
  const fonts = [fontStack];
  const text = labelField(lang);
  const width = (z) => [
    "interpolate",
    ["linear"],
    ["zoom"],
    ...z.flat()
  ];
  const layers = [
    // ── Background (land / paper) ──────────────────────────────────────────────
    { id: "background", type: "background", paint: { "background-color": c.background } },
    // ── Water & greenery ───────────────────────────────────────────────────────
    {
      id: "water",
      type: "fill",
      source: SRC,
      "source-layer": "water",
      filter: ["!=", ["get", "intermittent"], 1],
      paint: { "fill-color": c.water }
    },
    {
      id: "green",
      type: "fill",
      source: SRC,
      "source-layer": "landcover",
      filter: ["in", ["get", "class"], ["literal", ["wood", "grass", "park", "forest", "scrub"]]],
      paint: { "fill-color": c.green, "fill-opacity": 0.6 }
    },
    {
      id: "waterway",
      type: "line",
      source: SRC,
      "source-layer": "waterway",
      minzoom: 9,
      paint: { "line-color": c.waterway, "line-width": width([[9, 0.5], [16, 2]]) }
    },
    // ── Roads: casing first, then fill (so casings sit under all fills) ─────────
    {
      id: "road-casing-major",
      type: "line",
      source: SRC,
      "source-layer": "transportation",
      minzoom: 6,
      filter: ["in", ["get", "class"], ["literal", ["motorway", "trunk", "primary"]]],
      layout: { "line-cap": "round", "line-join": "round" },
      paint: { "line-color": c.roadCasing, "line-width": width([[6, 1.2], [12, 5], [16, 14]]) }
    },
    {
      id: "road-minor",
      type: "line",
      source: SRC,
      "source-layer": "transportation",
      minzoom: 12,
      filter: ["in", ["get", "class"], ["literal", ["minor", "service", "track"]]],
      layout: { "line-cap": "round", "line-join": "round" },
      paint: { "line-color": c.roadMinor, "line-width": width([[12, 0.6], [16, 4], [18, 10]]) }
    },
    {
      id: "road-secondary",
      type: "line",
      source: SRC,
      "source-layer": "transportation",
      minzoom: 9,
      filter: ["in", ["get", "class"], ["literal", ["secondary", "tertiary"]]],
      layout: { "line-cap": "round", "line-join": "round" },
      paint: { "line-color": c.roadSecondary, "line-width": width([[9, 0.8], [13, 3], [17, 11]]) }
    },
    {
      id: "road-major",
      type: "line",
      source: SRC,
      "source-layer": "transportation",
      minzoom: 6,
      filter: ["in", ["get", "class"], ["literal", ["motorway", "trunk", "primary"]]],
      layout: { "line-cap": "round", "line-join": "round" },
      paint: { "line-color": c.roadMajor, "line-width": width([[6, 0.6], [12, 3.5], [16, 11]]) }
    },
    {
      id: "rail",
      type: "line",
      source: SRC,
      "source-layer": "transportation",
      minzoom: 11,
      filter: ["==", ["get", "class"], "rail"],
      paint: { "line-color": c.rail, "line-width": width([[11, 0.5], [16, 2]]) }
    },
    // ── Road-name labels (follow the line) ─────────────────────────────────────
    {
      id: "road-name",
      type: "symbol",
      source: SRC,
      "source-layer": "transportation_name",
      minzoom: 13,
      filter: ["in", ["get", "class"], ["literal", ["motorway", "trunk", "primary", "secondary", "tertiary", "minor"]]],
      layout: {
        "symbol-placement": "line",
        "text-field": text,
        "text-font": fonts,
        "text-size": width([[13, 10], [18, 13]]),
        "text-max-angle": 30
      },
      paint: { "text-color": c.roadText, "text-halo-color": c.textHalo, "text-halo-width": 1.4 }
    },
    // ── Place labels: villages/suburbs, towns, then cities (drawn last = on top) ─
    {
      id: "place-village",
      type: "symbol",
      source: SRC,
      "source-layer": "place",
      minzoom: 11,
      filter: ["in", ["get", "class"], ["literal", ["village", "hamlet", "suburb", "neighbourhood", "quarter"]]],
      layout: {
        "text-field": text,
        "text-font": fonts,
        "text-size": width([[11, 10], [16, 14]]),
        "text-max-width": 8,
        "text-padding": 2
      },
      paint: { "text-color": c.placeText, "text-halo-color": c.textHalo, "text-halo-width": 1.4, "text-opacity": 0.85 }
    },
    {
      id: "place-town",
      type: "symbol",
      source: SRC,
      "source-layer": "place",
      minzoom: 8,
      filter: ["==", ["get", "class"], "town"],
      layout: {
        "text-field": text,
        "text-font": fonts,
        "text-size": width([[8, 11], [14, 16]]),
        "text-max-width": 8,
        "text-padding": 2
      },
      paint: { "text-color": c.placeText, "text-halo-color": c.textHalo, "text-halo-width": 1.6 }
    },
    {
      id: "place-city",
      type: "symbol",
      source: SRC,
      "source-layer": "place",
      minzoom: 5,
      filter: ["in", ["get", "class"], ["literal", ["city", "state_capital"]]],
      layout: {
        "text-field": text,
        "text-font": fonts,
        "text-size": width([[5, 12], [12, 20]]),
        "text-max-width": 8,
        "text-padding": 2
      },
      paint: { "text-color": c.placeText, "text-halo-color": c.textHalo, "text-halo-width": 1.8 }
    }
  ];
  return {
    version: 8,
    glyphs: glyphsUrl,
    sources: {
      [SRC]: { type: "vector", url: `pmtiles://${pmtilesUrl}`, attribution }
    },
    layers
  };
}

export { VARDHAN_TILES_ORIGIN, vectorBasemapStyle };
